import torch
import torch.nn as nn
import triton
import triton.language as tl


def _gemm_configs():
    return [
        triton.Config({"BLOCK_M": 32, "BLOCK_N": 32, "BLOCK_K": 32, "GROUP_SIZE_M": 4}),
    ]


@triton.autotune(configs=_gemm_configs(), key=["M", "N", "K"])
@triton.jit
def _gemm_bias_kernel(
    x_ptr,
    w_ptr,
    b_ptr,
    y_ptr,
    M,
    N,
    K,
    stride_xm: tl.constexpr,
    stride_xk: tl.constexpr,
    stride_wk: tl.constexpr,
    stride_wn: tl.constexpr,
    stride_ym: tl.constexpr,
    stride_yn: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_SIZE_M: tl.constexpr,
):
    pid = tl.program_id(0)
    num_pid_m = tl.cdiv(M, BLOCK_M)
    num_pid_n = tl.cdiv(N, BLOCK_N)
    num_pid_in_group = GROUP_SIZE_M * num_pid_n
    group_id = pid // num_pid_in_group
    first_pid_m = group_id * GROUP_SIZE_M
    group_size_m = tl.minimum(num_pid_m - first_pid_m, GROUP_SIZE_M)
    pid_m = first_pid_m + ((pid % num_pid_in_group) % group_size_m)
    pid_n = (pid % num_pid_in_group) // group_size_m

    x_desc = tl.make_tensor_descriptor(
        base=x_ptr,
        shape=(M, K),
        strides=(stride_xm, stride_xk),
        block_shape=(BLOCK_M, BLOCK_K),
    )
    w_desc = tl.make_tensor_descriptor(
        base=w_ptr,
        shape=(K, N),
        strides=(stride_wk, stride_wn),
        block_shape=(BLOCK_K, BLOCK_N),
    )

    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
    for off_k in range(0, K, BLOCK_K):
        a = x_desc.load([pid_m * BLOCK_M, off_k])
        b = w_desc.load([off_k, pid_n * BLOCK_N])
        acc += tl.dot(a, b)

    offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)
    bias = tl.load(b_ptr + offs_n, mask=offs_n < N, other=0.0).to(tl.float32)
    acc += bias[None, :]
    acc = 0.5 * acc * (1.0 + tl.math.erf(acc * 0.7071067811865476))

    y_desc = tl.make_tensor_descriptor(
        base=y_ptr,
        shape=(M, N),
        strides=(stride_ym, stride_yn),
        block_shape=(BLOCK_M, BLOCK_N),
    )
    y_desc.store([pid_m * BLOCK_M, pid_n * BLOCK_N], acc.to(y_ptr.type.element_ty))


def _softmax_configs():
    configs = [triton.Config({"BLOCK_N": 32},)]
    return configs


@triton.autotune(configs=_softmax_configs(), key=["N"])
@triton.jit
def _softmax_inplace_kernel(
    ptr,
    M,
    N,
    stride_m,
    stride_n,
    BLOCK_N: tl.constexpr,
):
    row = tl.program_id(0)
    if row >= M:
        return
    row64 = row.to(tl.int64)
    row_ptr = ptr + row64 * stride_m
    neg_inf = -float("inf")
    offs_n = tl.arange(0, BLOCK_N)

    row_max = tl.full((), neg_inf, tl.float32)
    for sn in tl.range(0, N, BLOCK_N):
        cols = sn + offs_n
        mask = cols < N
        vals = tl.load(
            row_ptr + cols.to(tl.int64) * stride_n, mask=mask, other=neg_inf
        ).to(tl.float32)
        row_max = tl.maximum(row_max, tl.max(vals, axis=0))

    row_sum = tl.zeros((), tl.float32)
    for sn in tl.range(0, N, BLOCK_N):
        cols = sn + offs_n
        mask = cols < N
        vals = tl.load(
            row_ptr + cols.to(tl.int64) * stride_n, mask=mask, other=neg_inf
        ).to(tl.float32)
        row_sum += tl.sum(tl.exp(vals - row_max), axis=0)

    inv_sum = 1.0 / row_sum
    for sn in tl.range(0, N, BLOCK_N):
        cols = sn + offs_n
        mask = cols < N
        vals = tl.load(
            row_ptr + cols.to(tl.int64) * stride_n, mask=mask, other=neg_inf
        ).to(tl.float32)
        probs = tl.exp(vals - row_max) * inv_sum
        tl.store(
            row_ptr + cols.to(tl.int64) * stride_n,
            probs.to(ptr.dtype.element_ty),
            mask=mask,
        )


def kernel_function(x, weight_kn, bias) -> torch.Tensor:
    M, K = x.shape
    _, N = weight_kn.shape

    out = torch.empty((M, N), device=x.device, dtype=x.dtype)
    grid_gemm = lambda META: (
        triton.cdiv(M, META["BLOCK_M"]) * triton.cdiv(N, META["BLOCK_N"]),
    )
    _gemm_bias_kernel[grid_gemm](
        x,
        weight_kn,
        bias,
        out,
        M,
        N,
        K,
        x.stride(0),
        x.stride(1),
        weight_kn.stride(0),
        weight_kn.stride(1),
        out.stride(0),
        out.stride(1),
    )

    _softmax_inplace_kernel[(M,)](
        out,
        M,
        N,
        out.stride(0),
        out.stride(1),
    )
    return out


batch_size = 1024
in_features = 4096
out_features = 4096


def get_inputs():
    return [torch.rand(batch_size, in_features)]


def get_init_inputs():
    return [in_features, out_features]


class Model(nn.Module):
    def __init__(self, in_features, out_features):
        super().__init__()
        self.linear = nn.Linear(in_features, out_features)
        self._weight_kn = None

    def forward(self, x):
        if self._weight_kn is None:
            w = self.linear.weight.data.to(dtype=x.dtype).contiguous()
            self.linear.weight.data = w
            self.linear.bias.data = self.linear.bias.data.to(dtype=x.dtype).contiguous()
            self._weight_kn = w.t().contiguous()
        return kernel_function(x.contiguous(), self._weight_kn, self.linear.bias)
